CREATE TABLE IF NOT EXISTS rate_limits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ip_address VARCHAR(45) NOT NULL,endpoint VARCHAR(100) NOT NULL,attempt_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_rate_limit_lookup(ip_address,endpoint,attempt_at));
CREATE TABLE IF NOT EXISTS admin_login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ip_address VARCHAR(45) NOT NULL,success TINYINT(1) NOT NULL,attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_admin_login(ip_address,attempted_at));
CREATE TABLE IF NOT EXISTS admin_audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_session_id VARCHAR(191),admin_label VARCHAR(100),action VARCHAR(100) NOT NULL,target_table VARCHAR(100),target_id BIGINT UNSIGNED,notes TEXT,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rsvps (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
